<?php declare(strict_types=1);$editing=$campaign!==null; ?>
<div class="actions"><div><span class="status">ADM · Financeiro</span><h1><?= $editing?'Editar campanha':'Nova campanha' ?></h1><p class="meta">O desconto será registrado na matrícula e não mudará retroativamente.</p></div><a class="button-secondary" href="<?= $escape($basePath) ?>/admin/finance/campaigns">Cancelar</a></div><?php if($error):?><p class="alert alert-danger"><?= $escape($error) ?></p><?php endif;?><section class="card"><div class="card-body"><form method="post" action="<?= $escape($basePath) ?>/admin/finance/campaigns<?= $editing?'/'.(int)$campaign['id']:'' ?>"><?= $csrfField ?><div class="form-grid"><div class="form-field"><label>Nome da campanha <span class="required">*</span></label><input name="name" maxlength="160" value="<?= $escape($campaign['name']??'') ?>" required></div><div class="form-field"><label>Percentual de desconto <span class="required">*</span></label><input name="discount_percent" type="number" min="0.01" max="100" step="0.01" value="<?= $editing?$escape(number_format((float)$campaign['discount_percent'],2,'.','')):'' ?>" required></div><div class="form-field"><label>Válida até <span class="required">*</span></label><input name="valid_until" type="date" min="<?= date('Y-m-d') ?>" value="<?= $escape($campaign['valid_until']??'') ?>" required></div></div><label class="check-option"><input type="checkbox" name="is_active" value="1"<?= !$editing||(int)$campaign['is_active']===1?' checked':'' ?>> Campanha ativa</label><div class="form-actions"><button class="button-primary" type="submit">Salvar campanha</button></div></form></div></section>
